css:
.switch {
  position: relative;
  display: inline-flex;
  width: 368px;
  height: 176px;
  background: linear-gradient(135deg, #78350f 0%, #451a03 50%, #290f02 100%);
  border-radius: 16px;
  box-shadow:
    inset 0 0 0 2px #b45309,
    inset 0 0 10px 4px rgba(0, 0, 0, 0.9),
    0 32px 64px -8px rgba(0, 0, 0, 0.95),
    0 0 0 6px #020617,
    0 0 0 10px #1e293b;
  cursor: pointer;
  overflow: hidden;
  transform: translateZ(0);
  transition:
    transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1),
    box-shadow 0.2s ease;
  user-select: none;
}

.switch:hover {
  transform: scale(1.02);
  box-shadow:
    inset 0 0 0 2px #d97706,
    inset 0 0 10px 4px rgba(0, 0, 0, 0.9),
    0 40px 80px -8px rgba(0, 0, 0, 1),
    0 0 0 6px #020617,
    0 0 0 10px #334155;
}

.switch:active {
  transform: scale(0.98);
}

.switch input {
  display: none;
}

.wood-grain {
  position: absolute;
  width: 100%;
  height: 100%;
  background-image: repeating-linear-gradient(
      12deg,
      transparent,
      transparent 8px,
      rgba(0, 0, 0, 0.06) 8px,
      rgba(0, 0, 0, 0.06) 12px
    ),
    repeating-linear-gradient(
      -8deg,
      transparent,
      transparent 16px,
      rgba(255, 255, 255, 0.04) 16px,
      rgba(255, 255, 255, 0.04) 20px
    );
  z-index: 1;
}

.diamonds {
  position: absolute;
  width: 100%;
  height: 100%;
  z-index: 2;
}

.diamond {
  position: absolute;
  width: 8px;
  height: 8px;
  background: radial-gradient(circle at 30% 30%, #f8fafc, #94a3b8);
  transform: rotate(45deg);
  box-shadow:
    inset 0 1px 2px rgba(0, 0, 0, 0.6),
    0 1px 1px rgba(255, 255, 255, 0.2);
}

.d1 {
  top: 8px;
  left: 92px;
}
.d2 {
  top: 8px;
  left: 180px;
}
.d3 {
  top: 8px;
  left: 268px;
}
.d4 {
  bottom: 8px;
  left: 92px;
}
.d5 {
  bottom: 8px;
  left: 180px;
}
.d6 {
  bottom: 8px;
  left: 268px;
}
.d7 {
  top: 84px;
  left: 8px;
}
.d8 {
  top: 84px;
  right: 8px;
}

.felt {
  position: absolute;
  top: 24px;
  left: 24px;
  right: 24px;
  bottom: 24px;
  background: #064e3b;
  border-radius: 8px;
  border: 12px solid #065f46;
  box-shadow:
    inset 0 8px 20px rgba(0, 0, 0, 0.9),
    0 4px 12px rgba(0, 0, 0, 0.9);
  background-image: radial-gradient(
      rgba(255, 255, 255, 0.07) 1px,
      transparent 1px
    ),
    radial-gradient(rgba(0, 0, 0, 0.15) 1px, transparent 1px);
  background-size: 4px 4px;
  background-position:
    0 0,
    2px 2px;
  z-index: 3;
  box-sizing: border-box;
}

.baulk-line {
  position: absolute;
  top: 0;
  left: 64px;
  width: 2px;
  height: 100%;
  background: rgba(255, 255, 255, 0.2);
}

.d-semi {
  position: absolute;
  top: 24px;
  left: 64px;
  width: 28px;
  height: 56px;
  border: 2px solid rgba(255, 255, 255, 0.2);
  border-left: none;
  border-radius: 0 28px 28px 0;
  box-sizing: border-box;
}

.pocket {
  position: absolute;
  width: 32px;
  height: 32px;
  background: #020617;
  border-radius: 50%;
  box-shadow:
    inset 4px 4px 8px rgba(0, 0, 0, 1),
    inset -2px -2px 6px rgba(255, 255, 255, 0.1),
    0 0 0 3px #381404,
    0 2px 4px rgba(0, 0, 0, 0.6);
  z-index: 4;
}

.p-tl {
  top: -16px;
  left: -16px;
}
.p-tr {
  top: -16px;
  right: -16px;
}
.p-bl {
  bottom: -16px;
  left: -16px;
}
.p-br {
  bottom: -16px;
  right: -16px;
}
.p-tm {
  top: -20px;
  left: calc(50% - 16px);
}
.p-bm {
  bottom: -20px;
  left: calc(50% - 16px);
}

.pocket-glow {
  position: absolute;
  bottom: -16px;
  right: -16px;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #10b981;
  box-shadow:
    0 0 24px 8px #10b981,
    inset 0 0 16px #fff;
  opacity: 0;
  z-index: 3;
}

.switch input:checked ~ .felt .pocket-glow {
  animation: glow-pulse 0.6s ease-out 1.1s forwards;
}

.balls-layer {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 10;
}

.ball {
  position: absolute;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  box-shadow:
    2px 6px 6px -1px rgba(0, 0, 0, 0.7),
    inset -4px -4px 6px rgba(0, 0, 0, 0.6),
    inset 2px 2px 6px rgba(255, 255, 255, 0.9);
}

.cue-ball {
  left: 32px;
  top: 42px;
  background: #f8fafc;
  z-index: 12;
}

.switch input:checked ~ .felt .balls-layer .cue-ball {
  animation: cue-ball-on 1.5s cubic-bezier(0.2, 0.8, 0.3, 1) forwards;
}

.switch input:not(:checked) ~ .felt .balls-layer .cue-ball {
  animation: cue-ball-off 1.2s cubic-bezier(0.4, 0, 0.2, 1) forwards;
}

.eight-ball {
  left: 144px;
  top: 43px;
  background: radial-gradient(circle at 35% 35%, #334155, #020617);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 11;
  overflow: hidden;
}

.eight-circle {
  width: 10px;
  height: 10px;
  background: #f8fafc;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: "Arial Black", Impact, sans-serif;
  font-size: 7px;
  font-weight: bold;
  color: #020617;
  box-shadow: inset 1px 1px 2px rgba(0, 0, 0, 0.4);
}

.switch input:checked ~ .felt .balls-layer .eight-ball {
  animation: eight-ball-on 1.5s cubic-bezier(0.25, 0.75, 0.4, 1) forwards;
}

.switch input:not(:checked) ~ .felt .balls-layer .eight-ball {
  animation: eight-ball-off 1.2s cubic-bezier(0.4, 0, 0.2, 1) forwards;
}

.switch input:checked ~ .felt .balls-layer .eight-ball .eight-circle {
  animation: ball-roll-on 1.5s cubic-bezier(0.25, 0.75, 0.4, 1) forwards;
}

.switch input:not(:checked) ~ .felt .balls-layer .eight-ball .eight-circle {
  animation: ball-roll-off 1.2s cubic-bezier(0.4, 0, 0.2, 1) forwards;
}

.cue-stick {
  position: absolute;
  top: 49.5px;
  left: -170px;
  width: 200px;
  height: 5px;
  background: linear-gradient(
    to right,
    #171717 0%,
    #171717 15%,
    #d4d4d8 15%,
    #d4d4d8 17%,
    #fbbf24 17%,
    #b45309 60%,
    #fef3c7 96%,
    #e2e8f0 96%,
    #e2e8f0 98%,
    #3b82f6 98%
  );
  border-radius: 2px;
  box-shadow: 0 12px 12px rgba(0, 0, 0, 0.7);
  z-index: 15;
  transform-origin: right center;
}

.switch input:checked ~ .felt .cue-stick {
  animation: cue-strike-on 1.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

.switch input:not(:checked) ~ .felt .cue-stick {
  animation: cue-strike-off 1.2s cubic-bezier(0.4, 0, 0.2, 1) forwards;
}

.impact-spark {
  position: absolute;
  top: 42px;
  left: 124px;
  width: 20px;
  height: 20px;
  background: radial-gradient(
    circle,
    #ffffff 10%,
    #60a5fa 40%,
    transparent 70%
  );
  border-radius: 50%;
  opacity: 0;
  transform: scale(0);
  z-index: 14;
  pointer-events: none;
}

.switch input:checked ~ .felt .impact-spark {
  animation: spark-flash 0.4s ease-out 0.35s forwards;
}

.overhead-light {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: radial-gradient(
    ellipse at 50% 50%,
    rgba(255, 255, 255, 0.1) 0%,
    rgba(0, 0, 0, 0.6) 100%
  );
  pointer-events: none;
  z-index: 20;
  border-radius: 8px;
}

.glass-glare {
  position: absolute;
  top: 6px;
  right: 6px;
  bottom: 6px;
  left: 6px;
  border-radius: 12px;
  background: linear-gradient(
    115deg,
    rgba(255, 255, 255, 0) 20%,
    rgba(255, 255, 255, 0.04) 25%,
    rgba(255, 255, 255, 0.12) 40%,
    rgba(255, 255, 255, 0) 45%
  );
  pointer-events: none;
  z-index: 30;
}

@keyframes cue-strike-on {
  0% {
    transform: translateX(0);
  }
  12% {
    transform: translateX(-30px);
    animation-timing-function: cubic-bezier(0.8, 0, 1, 1);
  }
  18% {
    transform: translateX(10px);
    animation-timing-function: ease-out;
  }
  26%,
  100% {
    transform: translateX(6px);
  }
}

@keyframes cue-strike-off {
  0%,
  100% {
    transform: translateX(0);
  }
}

@keyframes cue-ball-on {
  0%,
  18% {
    transform: translate(0, 0);
  }
  38% {
    transform: translate(92px, 0);
    animation-timing-function: cubic-bezier(0.2, 0.8, 0.4, 1);
  }
  75%,
  100% {
    transform: translate(110px, -20px);
  }
}

@keyframes cue-ball-off {
  0% {
    transform: translate(110px, -20px);
  }
  10% {
    transform: translate(92px, 0);
    animation-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
  }
  35%,
  100% {
    transform: translate(0, 0);
  }
}

@keyframes eight-ball-on {
  0%,
  38% {
    transform: translate(0, 0) scale(1);
    opacity: 1;
  }
  80% {
    transform: translate(142px, 51px) scale(1);
    opacity: 1;
    animation-timing-function: ease-in;
  }
  90%,
  100% {
    transform: translate(146px, 55px) scale(0.2);
    opacity: 0;
  }
}

@keyframes eight-ball-off {
  0% {
    transform: translate(146px, 55px) scale(0.2);
    opacity: 0;
  }
  10% {
    transform: translate(142px, 51px) scale(1);
    opacity: 1;
    animation-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
  }
  35%,
  100% {
    transform: translate(0, 0) scale(1);
    opacity: 1;
  }
}

@keyframes ball-roll-on {
  0%,
  38% {
    transform: rotateY(0deg) rotateX(0deg) rotateZ(0deg);
  }
  80%,
  100% {
    transform: rotateY(360deg) rotateX(160deg) rotateZ(45deg);
  }
}

@keyframes ball-roll-off {
  0% {
    transform: rotateY(360deg) rotateX(160deg) rotateZ(45deg);
  }
  35%,
  100% {
    transform: rotateY(0deg) rotateX(0deg) rotateZ(0deg);
  }
}

@keyframes spark-flash {
  0% {
    opacity: 0;
    transform: scale(0);
  }
  20% {
    opacity: 1;
    transform: scale(1.5);
  }
  100% {
    opacity: 0;
    transform: scale(2.5);
  }
}

@keyframes glow-pulse {
  0% {
    opacity: 0;
    transform: scale(0.8);
  }
  40% {
    opacity: 1;
    transform: scale(1.1);
  }
  100% {
    opacity: 0;
    transform: scale(1);
  }
}
